.icon-nav-base, .btn {
  border: none;
  cursor: pointer;
  background: none;
}

.btn {
  height: unset;
}

.btn-skew {
  background-color: red;
  position: relative;
  overflow: hidden;
  color: #fff;
  z-index: 1;
}
.btn-skew::before {
  content: "";
  position: absolute;
  top: 0;
  left: -80%;
  height: 100%;
  width: 0;
  transform: skew(30deg);
  background-color: green;
  transition: 0.5s ease-in-out;
  transform-origin: top left;
  z-index: -1;
}
.btn-skew:hover::before {
  height: 100%;
  width: 200%;
}
.btn-skew a {
  color: #fff;
}

.btn-popup {
  background-color: #9a009a;
  position: relative !important;
  overflow: hidden;
  z-index: 1;
  left: 0;
}
.btn-popup::before {
  content: "";
  width: 0px;
  aspect-ratio: 1;
  border-radius: 50%;
  position: absolute;
  left: var(--x);
  top: var(--y);
  background-color: orangered;
  transform: translate(-50%, -50%);
  z-index: -1;
  transition: width 0.5s ease-out;
}
.btn-popup:hover::before {
  width: 300px;
}
.btn-popup a {
  color: #fff;
}

.icon-nav-base {
  position: relative;
  width: 50px;
  height: 50px;
  display: none;
  transition: 0.3s ease-in-out;
  overflow: hidden;
}
.icon-nav-base span {
  width: 40px;
  height: 3px;
  background-color: red;
  border-radius: 50px;
  transition: 0.3s ease-in-out;
  position: absolute;
}
.icon-nav-base span:nth-child(1) {
  top: 15px;
}
.icon-nav-base span:nth-child(2) {
  top: 25px;
}
.icon-nav-base span:nth-child(3) {
  top: 35px;
}
.icon-nav-base.active span:nth-child(1) {
  top: 50%;
  transform: rotate(45deg);
}
.icon-nav-base.active span:nth-child(2) {
  transform: translateX(-50px);
  opacity: 0;
}
.icon-nav-base.active span:nth-child(3) {
  top: 50%;
  transform: rotate(315deg);
}

.responsive-link {
  position: absolute;
  background-color: red;
  overflow: hidden;
  width: 100%;
  z-index: 1023;
  left: 0;
  height: 0;
  min-height: 0;
}
.responsive-link li {
  padding: 10px 15px;
}
.responsive-link li a {
  font-size: 16px;
}

.side-menu {
  background-color: hsl(250, 6%, 20%);
  position: fixed;
  height: 100%;
  width: 340px;
}

